@page "/settings"
@namespace sv_9d5cb79dc1414b16b53dff59503870fb.Components.Pages.Settings
@rendermode InteractiveServer

<PageTitle>Settings</PageTitle>

<div class="container-fluid py-4">
    <h2 class="mb-4">Settings</h2>
    <div class="row">
        <div class="col-md-3 col-lg-2">
            <SettingsSidebar ActiveSection="@_activeSection" OnSectionChanged="SetActiveSection" />
        </div>
        <div class="col-md-9 col-lg-10">
            @switch (_activeSection)
            {
                case "Profile":
                    <ProfileSection />
                    break;
                case "Notifications":
                    <NotificationsSection />
                    break;
                case "Security":
                    <SecuritySection />
                    break;
                case "Appearance":
                    <AppearanceSection />
                    break;
            }
        </div>
    </div>
</div>

@code {
    private string _activeSection = "Profile";

    private void SetActiveSection(string section)
    {
        _activeSection = section;
    }
}

